                    obj[key] = fdp.ConsumeInt(1000)
                elif choice == 1:
                    obj[key] = fdp.ConsumeUnicode(100)
                else:
                    obj[key] = fdp.ConsumeBool()

            sort_keys = fdp.ConsumeBool()
            ujson.encode(obj, sort_keys=sort_keys)
